// Package gen turns a scan.Result into the source of trilha_gen.go.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strings"
	"text/template"

	"github.com/emersonjoe/trilha/internal/scan"
)

// FileName is the generated file's name at the project root.
const FileName = "trilha_gen.go"

// RuntimeImport is the import path of the trilha runtime.
const RuntimeImport = "github.com/emersonjoe/trilha"

var tmpl = template.Must(template.New("gen").Funcs(template.FuncMap{
	"refs":  refList,
	"quote": func(s string) string { return fmt.Sprintf("%q", s) },
}).Parse(`// Code generated by trilha. DO NOT EDIT.

//go:generate trilha gen

package {{.Pkg}}

import (
{{- if .HasPublic}}
	"embed"
{{- end}}

	trilha "{{.Runtime}}"
{{- range .Imports}}
	{{.Alias}} "{{.Path}}"
{{- end}}
)
{{if .HasPublic}}
//go:embed public
var publicFS embed.FS
{{end}}
{{if .Embedded -}}
// NewApp builds the application. The host binary calls it and mounts the
// result: mux.Handle("/", NewApp().Handler()).
{{else -}}
// newApp builds the application. Tests can call it and use a.Handler().
{{end -}}
func {{.Ctor}}() *trilha.App {
	cfg := trilha.ConfigFromEnv()
{{- if .HasPublic}}
	cfg.Public = trilha.PublicFS(publicFS, "public")
{{- else}}
	cfg.Public = trilha.PublicFS(nil, "public")
{{- end}}
{{- if .ConfigFunc}}
{{- if .ConfigReturnsError}}
	if err := {{.ConfigFunc.Alias}}.{{.ConfigFunc.Func}}(&cfg); err != nil {
		trilha.Fatal(err)
	}
{{- else}}
	{{.ConfigFunc.Alias}}.{{.ConfigFunc.Func}}(&cfg)
{{- end}}
{{- end}}
	a := trilha.New(cfg)
{{- if .Setup}}
	if err := {{.Setup.Alias}}.{{.Setup.Func}}(a); err != nil {
		trilha.Fatal(err)
	}
{{- end}}
{{- if .ShutdownFunc}}
	a.OnShutdown({{.ShutdownFunc.Alias}}.{{.ShutdownFunc.Func}})
{{- end}}
{{- if .RootLayout}}
	a.SetRootLayout({{.RootLayout.Alias}}.{{.RootLayout.Func}})
{{- end}}
{{- if .NotFound}}
	a.SetNotFound({{.NotFound.Alias}}.{{.NotFound.Func}})
{{- end}}
{{- if .ErrorPage}}
	a.SetErrorPage({{.ErrorPage.Alias}}.{{.ErrorPage.Func}})
{{- end}}
{{- range .Routes}}
{{- $r := .}}
	a.Register(trilha.Route{
		Pattern: {{quote .Pattern}},
{{- if .HasPage}}
		Page: {{.Alias}}.Page,
{{- end}}
{{- if .KindRef}}
		Kind: {{.KindRef.Alias}}.{{.KindRef.Func}},
{{- end}}
{{- if .HasCORS}}
		CORS: &{{.Alias}}.CORS,
{{- end}}
{{- if .Methods}}
		Methods: map[string]trilha.HandlerFunc{
{{- range .Methods}}
			{{quote .}}: {{$r.Alias}}.{{.}},
{{- end}}
		},
{{- end}}
{{- if .Layouts}}
		Layouts: []trilha.LayoutFunc{ {{refs .Layouts}} },
{{- end}}
{{- if .Middlewares}}
		Middlewares: []trilha.MiddlewareFunc{ {{refs .Middlewares}} },
{{- end}}
{{- if .MiddlewaresByMethod}}
		MiddlewaresByMethod: map[string][]trilha.MiddlewareFunc{
{{- range .MethodChains}}
			{{quote .Method}}: { {{refs .Refs}} },
{{- end}}
		},
{{- end}}
	})
{{- end}}
	return a
}
{{- if .NeedsMain}}

func main() {
	trilha.Run(newApp())
}
{{- end}}
`))

func refList(rs []scan.Ref) string {
	parts := make([]string, len(rs))
	for i, r := range rs {
		parts[i] = r.Alias + "." + r.Func
	}
	return strings.Join(parts, ", ")
}

type routeView struct {
	scan.Route
	Alias string
}

// methodChain is one entry of MiddlewaresByMethod, in a fixed order so the
// generated file does not churn between runs.
type methodChain struct {
	Method string
	Refs   []scan.Ref
}

// MethodChains lists the per-method chains sorted by method.
func (r routeView) MethodChains() []methodChain {
	out := make([]methodChain, 0, len(r.MiddlewaresByMethod))
	for m, refs := range r.MiddlewaresByMethod {
		out = append(out, methodChain{Method: m, Refs: refs})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Method < out[j].Method })
	return out
}

type view struct {
	*scan.Result
	Runtime string
	Pkg     string
	Routes  []routeView
}

// Embedded is true when the app is a package inside another binary rather than
// the binary itself: no func main, and a constructor the host can call.
func (v view) Embedded() bool { return v.Pkg != "main" }

// Ctor is the constructor's name: exported when someone else has to call it.
func (v view) Ctor() string {
	if v.Embedded() {
		return "NewApp"
	}
	return "newApp"
}

// NeedsMain reports whether the generator must supply func main() itself.
func (v view) NeedsMain() bool { return !v.Embedded() && !v.HasMain }

// Generate renders the gofmt'ed source of trilha_gen.go.
func Generate(res *scan.Result) ([]byte, error) {
	v := view{Result: res, Runtime: RuntimeImport, Pkg: res.Package}
	if v.Pkg == "" {
		v.Pkg = "main"
	}
	routes := append([]scan.Route{}, res.Routes...)
	sort.Slice(routes, func(i, j int) bool { return routes[i].Pattern < routes[j].Pattern })
	for _, r := range routes {
		v.Routes = append(v.Routes, routeView{Route: r, Alias: r.Alias})
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, v); err != nil {
		return nil, err
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("gen: formatting generated code: %w\n%s", err, buf.String())
	}
	return src, nil
}
